function mystery(arr) {
  let a = -Infinity;
  let b = -Infinity;
  for (const x of arr) {
    if (x > a) {
      b = a;
      a = x;
    } else if (x > b && x < a) {
      b = x;
    }
  }
  return b;
}
console.log(mystery([4, 9, 2, 9, 7]));

function power(base, exp) {
  if (exp === 1) return 1;
  return base * power(base, exp - 1);
}

